/*
 * Dailies web app service worker: the hub works offline. Generated by web/build.mjs, which fills in
 * the version and the file list; a new deploy has a new version, so the old cache is dropped.
 * Pages are fetched from the network first (so updates arrive), files from the cache first (their
 * URLs carry the version).
 */
const VERSION = '__VERSION__';
const CACHE = `dailies-${VERSION}`;
const FILES = __FILES__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((c) => c.addAll(FILES.map((u) => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('dailies-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  if (req.mode === 'navigate') {
    const cachedShell = () => caches.open(CACHE).then((c) => c.match('./').then((r) => r || c.match('./index.html')));
    event.respondWith(fetch(req, { cache: 'no-cache' }).then((res) => {
      if (res.ok) {
        const copy = res.clone();
        event.waitUntil(caches.open(CACHE).then((c) => c.put('./', copy)));
        return res;
      }
      return cachedShell().then((r) => r || res);
    }).catch(cachedShell));
    return;
  }
  event.respondWith(caches.open(CACHE).then((c) => c.match(req).then((hit) => hit || fetch(req).then((res) => {
    if (res.ok) {
      const copy = res.clone();
      event.waitUntil(c.put(req, copy));
    }
    return res;
  }))));
});
